import{ht as e,nt as t,o as n,tt as r}from"./chunks/framework.CuG1B4CC.js";var i=JSON.parse(`{"title":"Frequently Asked Questions (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}`),a={name:`faq.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="frequently-asked-questions-faq" tabindex="-1">Frequently Asked Questions (FAQ) <a class="header-anchor" href="#frequently-asked-questions-faq" aria-label="Permalink to “Frequently Asked Questions (FAQ)”">​</a></h1><h2 id="general-installation" tabindex="-1">General &amp; Installation <a class="header-anchor" href="#general-installation" aria-label="Permalink to “General &amp; Installation”">​</a></h2><h3 id="q-why-do-i-get-a-segmentation-fault-when-running-parallel-sd-vector-annotation-128" tabindex="-1">Q: Why do I get a Segmentation Fault when running <code>parallel_sd_vector_annotation_128</code>? <a class="header-anchor" href="#q-why-do-i-get-a-segmentation-fault-when-running-parallel-sd-vector-annotation-128" aria-label="Permalink to “Q: Why do I get a Segmentation Fault when running parallel_sd_vector_annotation_128?”">​</a></h3><p><strong>A</strong>: This is caused by a C++ ABI layout mismatch in SDSL-lite. The class <code>sd_vector_builder</code> has its constructor inside <code>libsdsl.so</code>, while <code>builder.set(i)</code> is compiled inline into your program. If <code>libsdsl.so</code> and your binary are compiled with different macros or optimization flags, memory member offsets mismatch.</p><p><strong>Solution</strong>: Ensure you compile <code>parallel_sd_vector_annotation_128.cpp</code> using the exact same SDSL-lite headers and library installed from <code>BRWT/construct_BRWT/external-libraries/sdsl-lite</code>.</p><hr><h3 id="q-can-i-run-inference-encoding-on-cpu-without-gpus" tabindex="-1">Q: Can I run inference / encoding on CPU without GPUs? <a class="header-anchor" href="#q-can-i-run-inference-encoding-on-cpu-without-gpus" aria-label="Permalink to “Q: Can I run inference / encoding on CPU without GPUs?”">​</a></h3><p><strong>A</strong>: Yes! Pass <code>--gpu_ids -1</code> to <code>gpus_inference_zstd.py</code> and <code>--device cpu</code> to <code>query_seq.py</code>.</p><hr><h3 id="q-what-is-the-difference-between-parallel-combine-sets-128-v2-log-and-parallel-combine-sets-128-v2-log-lowmem" tabindex="-1">Q: What is the difference between <code>parallel_combine_sets_128_v2_log</code> and <code>parallel_combine_sets_128_v2_log_lowmem</code>? <a class="header-anchor" href="#q-what-is-the-difference-between-parallel-combine-sets-128-v2-log-and-parallel-combine-sets-128-v2-log-lowmem" aria-label="Permalink to “Q: What is the difference between parallel_combine_sets_128_v2_log and parallel_combine_sets_128_v2_log_lowmem?”">​</a></h3><p><strong>A</strong>:</p><ul><li><code>v2_log</code> loads <strong>all</strong> embedding files into RAM at once. Use it only when dataset size fits within physical memory.</li><li><code>v2_log_lowmem</code> breaks input files into memory-budgeted chunks (e.g. <code>--chunk-gb 64</code>), sorts each chunk, spills to temporary disk files, and performs a k-way stream merge. Use this for large or petabase-scale datasets.</li></ul><hr><h3 id="q-do-i-need-python-faiss-installed-to-run-query-servers" tabindex="-1">Q: Do I need Python <code>faiss</code> installed to run query servers? <a class="header-anchor" href="#q-do-i-need-python-faiss-installed-to-run-query-servers" aria-label="Permalink to “Q: Do I need Python faiss installed to run query servers?”">​</a></h3><p><strong>A</strong>: No. Meshmetal uses a standalone C++ binary index (<code>index_mmap.bin</code>) and HTTP REST server (<code>faiss_server.bin</code>). The Python client <code>faiss_client.py</code> communicates with <code>faiss_server.bin</code> over HTTP REST using standard <code>requests</code>.</p><hr><h3 id="q-how-do-i-adjust-query-search-sensitivity-vs-speed" tabindex="-1">Q: How do I adjust query search sensitivity vs speed? <a class="header-anchor" href="#q-how-do-i-adjust-query-search-sensitivity-vs-speed" aria-label="Permalink to “Q: How do I adjust query search sensitivity vs speed?”">​</a></h3><p><strong>A</strong>:</p><ul><li><strong><code>nflip</code></strong>: Controls how many bit flips are evaluated during 16-bit prefix bucket probing. Higher values (e.g. <code>5</code> or <code>6</code>) increase candidate coverage but take longer to search.</li><li><strong><code>hamming_thres</code></strong>: Maximum Hamming distance cutoff for candidates (default <code>28</code>).</li><li><strong><code>min_coverage</code></strong>: Minimum sequence coverage required to report a matching accession (e.g. <code>0.2</code> for 20% coverage).</li></ul>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};